web:WebActor.InstanceScript:

if !EndsWith(URL,"/") then URL:=URL+"/";
RepresentURL:=URL+"represent";

ImageFiles:=join(
  System.IO.Directory.GetFiles(ImageDBFolder,"*.png",System.IO.SearchOption.AllDirectories),
  System.IO.Directory.GetFiles(ImageDBFolder,"*.jpg",System.IO.SearchOption.AllDirectories));
ImageCount:=count(ImageFiles);
LogNotice("Images found in database: "+Str(ImageCount));

Graphs.CustomGraph:

[Labels,Counts]:=Histogram(TestApi,1,10,10);
G:=VerticalBars(str(1..10),Counts);
G.LabelX:="Neuron";
G.LabelY:="Number of GETs";
G.Title:="Distribution of number of GET calls";
G


[Labels,Counts]:=Histogram(VectorizeFace,1,10,10);
G:=VerticalBars(str(1..10),Counts);
G.LabelX:="Neuron";
G.LabelY:="Number of POSTs";
G.Title:="Distribution of number of POST calls";
G
